-- Hyprland configuration (Lua format, Hyprland >= 0.55)
-- Wiki: https://wiki.hypr.land/Configuring/Start/
--
-- Each part lives in its own file under modules/.
-- Colors, wallpaper and cursor come from the active theme (current-theme.lua),
-- generated by dots-apply-theme. To switch themes: Alt + C.

local theme = require("modules.theme")

require("modules.monitors")
require("modules.environment")(theme)
require("modules.autostart")(theme)
require("modules.appearance")(theme)
require("modules.input")
require("modules.keybinds")
require("modules.rules")
